var t=`0141-harissa-armenian-wheat-porridge`;var n=`world-0141`;var a=`AM`;var s=`western-asia`;var r=4;var o=240;var m={en:`Harissa (Armenian Wheat Porridge)`,ua:`Харіса (вірменська пшенична каша)`};var d={en:`A classic dish from Armenia, featuring whole chicken, wheat berries, unsalted butter. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: ціла курка, зерна пшениці, несолоне вершкове масло. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 145 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 145 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:145,i:[[`whole-chicken`,850,`g`],[`wheat-berries`,380,`g`],[`water`,2200,`ml`],[`table-salt`,6,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 80 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 80 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:80,i:[[`unsalted-butter`,90,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,null,`to_taste`]]}];var h={slug:t,id:n,country:`AM`,region:s,servings:4,minutes:240,title:m,text:d,steps:g};export{a as country,h as default,n as id,o as minutes,s as region,r as servings,t as slug,g as steps,d as text,m as title};